-- WARNING: This script recreates the exam tables and functions.
create extension if not exists pgcrypto;
drop table if exists public.answers cascade;drop table if exists public.attempts cascade;drop table if exists public.tutor_sessions cascade;drop table if exists public.questions cascade;drop table if exists public.exams cascade;
create table if not exists public.teachers(user_id uuid primary key references auth.users(id) on delete cascade);
create table public.exams(id uuid primary key default gen_random_uuid(),title text not null,duration_minutes int not null default 30 check(duration_minutes between 1 and 300),created_by uuid not null references auth.users(id),created_at timestamptz default now());
create table public.questions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id) on delete cascade,position int not null,text text not null,choices jsonb not null,correct_index int not null,unique(exam_id,position));
create table public.tutor_sessions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id) on delete cascade,status text not null default 'waiting' check(status in('waiting','live','finished')),current_position int not null default -1,started_at timestamptz default now(),ended_at timestamptz);
create unique index one_open_session on public.tutor_sessions((status in('waiting','live'))) where status in('waiting','live');
create table public.attempts(id uuid primary key default gen_random_uuid(),token uuid unique not null default gen_random_uuid(),session_id uuid not null references public.tutor_sessions(id) on delete cascade,student_id text not null,student_name text not null,score int not null default 0,joined_at timestamptz default now(),unique(session_id,student_id));
create table public.answers(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.attempts(id) on delete cascade,question_id uuid not null references public.questions(id) on delete cascade,choice_index int not null,is_correct boolean not null,answered_at timestamptz default now(),unique(attempt_id,question_id));
alter table public.teachers enable row level security;alter table public.exams enable row level security;alter table public.questions enable row level security;alter table public.tutor_sessions enable row level security;alter table public.attempts enable row level security;alter table public.answers enable row level security;
revoke all on public.teachers,public.exams,public.questions,public.tutor_sessions,public.attempts,public.answers from anon,authenticated;
create or replace function public.is_teacher() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from teachers where user_id=auth.uid())$$;
create or replace function public.teacher_exam_get() returns jsonb language plpgsql security definer set search_path=public as $$declare e exams;r jsonb;begin if not is_teacher() then raise exception 'Unauthorized';end if;select * into e from exams order by created_at desc limit 1;if e.id is null then return null;end if;select jsonb_build_object('id',e.id,'title',e.title,'durationMinutes',e.duration_minutes,'questions',coalesce(jsonb_agg(jsonb_build_object('text',q.text,'choices',q.choices,'correct',q.correct_index) order by q.position),'[]')) into r from questions q where q.exam_id=e.id;return r;end$$;
create or replace function public.teacher_exam_save(payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare eid uuid;x jsonb;n int:=0;begin if not is_teacher() then raise exception 'Unauthorized';end if;if coalesce(jsonb_array_length(payload->'questions'),0) not between 1 and 200 then raise exception 'จำนวนข้อไม่ถูกต้อง';end if;insert into exams(title,duration_minutes,created_by) values(trim(payload->>'title'),(payload->>'durationMinutes')::int,auth.uid()) returning id into eid;for x in select * from jsonb_array_elements(payload->'questions') loop if jsonb_array_length(x->'choices') not between 2 and 6 then raise exception 'ตัวเลือกต้องมี 2-6 ตัวเลือก';end if;insert into questions(exam_id,position,text,choices,correct_index) values(eid,n,trim(x->>'text'),x->'choices',(x->>'correct')::int);n=n+1;end loop;return jsonb_build_object('ok',true,'examId',eid);end$$;
create or replace function public.teacher_round_start() returns jsonb language plpgsql security definer set search_path=public as $$declare eid uuid;sid uuid;begin if not is_teacher() then raise exception 'Unauthorized';end if;update tutor_sessions set status='finished',ended_at=now() where status in('waiting','live');select id into eid from exams order by created_at desc limit 1;if eid is null then raise exception 'ยังไม่มีชุดข้อสอบ';end if;insert into tutor_sessions(exam_id,status,current_position) values(eid,'waiting',-1) returning id into sid;return jsonb_build_object('sessionId',sid);end$$;
create or replace function public.teacher_release_next() returns jsonb language plpgsql security definer set search_path=public as $$declare s tutor_sessions;t int;begin if not is_teacher() then raise exception 'Unauthorized';end if;select * into s from tutor_sessions where status in('waiting','live') order by started_at desc limit 1 for update;if s.id is null then raise exception 'ยังไม่มีรอบติว';end if;select count(*) into t from questions where exam_id=s.exam_id;if s.current_position+1>=t then raise exception 'ครบทุกข้อแล้ว กรุณาจบการติว';end if;update tutor_sessions set status='live',current_position=current_position+1 where id=s.id;return jsonb_build_object('ok',true);end$$;
create or replace function public.teacher_round_finish() returns void language plpgsql security definer set search_path=public as $$begin if not is_teacher() then raise exception 'Unauthorized';end if;update tutor_sessions set status='finished',ended_at=now() where status in('waiting','live');end$$;
create or replace function public.teacher_control_state() returns jsonb language plpgsql security definer set search_path=public as $$declare e exams;s tutor_sessions;t int;students int;answered int;corrects int;begin if not is_teacher() then raise exception 'Unauthorized';end if;select * into e from exams order by created_at desc limit 1;if e.id is null then return null;end if;select count(*) into t from questions where exam_id=e.id;select * into s from tutor_sessions where exam_id=e.id order by started_at desc limit 1;if s.id is not null then select count(*) into students from attempts where session_id=s.id;select count(*),count(*) filter(where a.is_correct) into answered,corrects from answers a join attempts at on at.id=a.attempt_id join questions q on q.id=a.question_id where at.session_id=s.id and q.position=s.current_position;end if;return jsonb_build_object('title',e.title,'total',t,'sessionStatus',case when s.id is null then 'none' else s.status end,'currentPosition',coalesce(s.current_position,-1),'studentCount',coalesce(students,0),'answeredCount',coalesce(answered,0),'correctCount',coalesce(corrects,0),'wrongCount',coalesce(answered,0)-coalesce(corrects,0));end$$;
create or replace function public.student_session_info() returns jsonb language sql security definer set search_path=public as $$select jsonb_build_object('title',e.title,'questionCount',(select count(*) from questions where exam_id=e.id),'status',s.status) from tutor_sessions s join exams e on e.id=s.exam_id where s.status in('waiting','live') order by s.started_at desc limit 1$$;
create or replace function public.student_join(p_student_id text,p_student_name text) returns jsonb language plpgsql security definer set search_path=public as $$declare s tutor_sessions;a attempts;begin if trim(p_student_id)='' or trim(p_student_name)='' then raise exception 'กรุณากรอกชื่อและเลขประจำตัว';end if;select * into s from tutor_sessions where status in('waiting','live') order by started_at desc limit 1;if s.id is null then raise exception 'ยังไม่มีรอบติวที่เปิดอยู่';end if;select * into a from attempts where session_id=s.id and student_id=trim(p_student_id);if a.id is null then insert into attempts(session_id,student_id,student_name) values(s.id,left(trim(p_student_id),50),left(trim(p_student_name),120)) returning * into a;end if;return jsonb_build_object('token',a.token);end$$;
create or replace function public.student_state(p_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a attempts;s tutor_sessions;q questions;ans answers;t int;choice_text text;begin select * into a from attempts where token=p_token;if a.id is null then raise exception 'ไม่พบข้อมูลนักเรียน';end if;select * into s from tutor_sessions where id=a.session_id;select count(*) into t from questions where exam_id=s.exam_id;if s.status='finished' then return jsonb_build_object('status','finished','score',a.score,'total',t);end if;if s.current_position<0 then return jsonb_build_object('status',s.status,'currentNumber',0,'total',t,'score',a.score);end if;select * into q from questions where exam_id=s.exam_id and position=s.current_position;select * into ans from answers where attempt_id=a.id and question_id=q.id;if ans.id is not null then choice_text=q.choices->>ans.choice_index;return jsonb_build_object('status',s.status,'currentNumber',q.position+1,'total',t,'answered',true,'correct',ans.is_correct,'choice',ans.choice_index,'choiceText',choice_text,'correctChoice',q.correct_index,'correctText',q.choices->>q.correct_index,'score',a.score);end if;return jsonb_build_object('status',s.status,'currentNumber',q.position+1,'total',t,'answered',false,'text',q.text,'choices',q.choices,'score',a.score);end$$;
create or replace function public.student_answer(p_token uuid,p_choice int) returns jsonb language plpgsql security definer set search_path=public as $$declare a attempts;s tutor_sessions;q questions;c boolean;begin select * into a from attempts where token=p_token for update;if a.id is null then raise exception 'ไม่พบข้อมูลนักเรียน';end if;select * into s from tutor_sessions where id=a.session_id;if s.status<>'live' or s.current_position<0 then raise exception 'ครูยังไม่ได้ส่งข้อสอบ';end if;select * into q from questions where exam_id=s.exam_id and position=s.current_position;if p_choice<0 or p_choice>=jsonb_array_length(q.choices) then raise exception 'คำตอบไม่ถูกต้อง';end if;c=p_choice=q.correct_index;insert into answers(attempt_id,question_id,choice_index,is_correct) values(a.id,q.id,p_choice,c);if c then update attempts set score=score+1 where id=a.id;end if;return jsonb_build_object('ok',true);exception when unique_violation then raise exception 'ข้อนี้ตอบแล้ว ไม่สามารถแก้ไขได้';end$$;
create or replace function public.teacher_results() returns jsonb language plpgsql security definer set search_path=public as $$declare s tutor_sessions;r jsonb;t int;begin if not is_teacher() then raise exception 'Unauthorized';end if;select * into s from tutor_sessions order by started_at desc limit 1;if s.id is null then return '[]';end if;select count(*) into t from questions where exam_id=s.exam_id;select coalesce(jsonb_agg(jsonb_build_object('attemptId',a.id,'studentId',a.student_id,'studentName',a.student_name,'score',a.score,'total',t,'finished',s.status='finished','answers',coalesce((select jsonb_agg(jsonb_build_object('question',q.position+1,'choice',z.choice_index,'correct',z.is_correct) order by q.position) from answers z join questions q on q.id=z.question_id where z.attempt_id=a.id),'[]')) order by a.joined_at),'[]') into r from attempts a where a.session_id=s.id;return r;end$$;
create or replace function public.teacher_reset_attempt(p_attempt_id uuid) returns void language plpgsql security definer set search_path=public as $$begin if not is_teacher() then raise exception 'Unauthorized';end if;delete from attempts where id=p_attempt_id;end$$;
create or replace function public.teacher_clear_results() returns void language plpgsql security definer set search_path=public as $$declare sid uuid;begin if not is_teacher() then raise exception 'Unauthorized';end if;select id into sid from tutor_sessions order by started_at desc limit 1;delete from attempts where session_id=sid;end$$;
grant execute on function public.student_session_info() to anon,authenticated;grant execute on function public.student_join(text,text) to anon,authenticated;grant execute on function public.student_state(uuid) to anon,authenticated;grant execute on function public.student_answer(uuid,int) to anon,authenticated;grant execute on function public.teacher_exam_get() to authenticated;grant execute on function public.teacher_exam_save(jsonb) to authenticated;grant execute on function public.teacher_round_start() to authenticated;grant execute on function public.teacher_release_next() to authenticated;grant execute on function public.teacher_round_finish() to authenticated;grant execute on function public.teacher_control_state() to authenticated;grant execute on function public.teacher_results() to authenticated;grant execute on function public.teacher_reset_attempt(uuid) to authenticated;grant execute on function public.teacher_clear_results() to authenticated;
